// Fallback simples de spintax se o workflow não estiver disponível
const text = $json.message_text || '';

function resolveSpintax(str) {
  while (str.includes('{')) {
    const match = str.match(/\{([^{}]+)\}/);
    if (!match) break;
    const options = match[1].split('|').map(o => o.trim());
    const selected = options[Math.floor(Math.random() * options.length)];
    str = str.replace(match[0], selected);
  }
  return str;
}

const resolved = resolveSpintax(text);

return {
  message_text: resolved
};

// Injeta variáveis
const text = $json.message_text || '';
const vars = $json.variables || {};

let result = text;
for (const [key, value] of Object.entries(vars)) {
  const pattern = new RegExp(`{{\s*${key}\s*}}`, 'g');
  result = result.replace(pattern, String(value));
}

return {
  message_text: result
};

